            @"vi": @"Cài đặt EID|Ngôn ngữ|Nội dung|Vị trí|Giao diện|Nâng cao|Tên vật phẩm|Biểu tượng vật phẩm|Chất lượng|Mô tả|Biểu tượng chỉ số sau mũi tên|Vị trí ngang|Vị trí dọc|Tỉ lệ|Chiều rộng văn bản|Độ đục văn bản|Nền mô tả|Độ đục nền|Dự đoán RNG (tiết lộ)|Chỉ số từ Void / Black Rune|Hiệu ứng ẩn hiện tại|Đặt lại|Hủy|EID Vật phẩm|Vật phẩm và biến hình|Vật phẩm|Phụ kiện|Phụ kiện đã nuốt|Đã hấp thụ bởi Void|Lá bài, rune và thuốc|Biến hình|Người chơi|Phụ kiện|Lá bài / rune|Thuốc|Thuốc lớn|Thuốc chưa xác định|Phòng xúc xắc|Phòng hiến tế|Vật phẩm|Không có mô tả|vật phẩm khác|100% giữ chiều rộng gốc. Tăng để có dòng dài hơn.|Khi tạm dừng, mô tả không trống luôn có nền.|Hiện kết quả ngẫu nhiên ẩn. Mặc định tắt.|Chạm để xem xúc xắc tiếp theo. Không đổi vật phẩm chủ động.|Chạm để xem vật phẩm tiếp theo.",
            @"zh_cn": @"EID设置|语言|内容|位置|外观|高级|道具名称|道具图标|品质|描述|箭头后的属性图标|水平位置|垂直位置|缩放|文本宽度|文本不透明度|描述背景|背景不透明度|RNG预测（剧透）|虚空 / 黑符文属性预览|当前隐藏效果|重置|取消|EID 道具|道具与变身|道具|饰品|吞下的饰品|被虚空吸收|卡牌、符文和药丸|变身|玩家|饰品|卡牌 / 符文|药丸|大药丸|未识别的药丸|骰子房|献祭房|道具|暂无描述|更多物品|100%保留原始宽度。增大可显示更长的行。|暂停时，非空描述始终显示背景。|显示隐藏的随机结果。默认关闭。|点击查看下一个骰子。不会切换主动道具。|点击查看下一个道具。"
        };
        NSMutableDictionary *result = [NSMutableDictionary dictionary];
        NSArray *keys = EIDUIKeys();
        for (NSString *language in rows) {
            NSArray *values = [rows[language] componentsSeparatedByString:@"|"];
            NSCAssert(values.count == keys.count, @"Incomplete EID UI translation: %@", language);
            if (values.count == keys.count) result[language] = [NSDictionary dictionaryWithObjects:values forKeys:keys];
        }
        strings = result.copy;
    });
    return strings;
}

NSString *EIDUIString(NSString *language, NSString *key) {
    return Strings()[language][key] ?: Strings()[@"en_us"][key] ?: key;
}

NSArray<NSString *> *EIDUILanguages(void) { return [Strings().allKeys sortedArrayUsingSelector:@selector(compare:)]; }
